if not xt.ally then
return nil
end
local yt=tonumber(wt.active_attack_stats and wt.active_attack_stats.attack_cooldown)or 60
return{types=xt.ally.types,time=xt.ally.time,cd=yt,uptime=math.min(1,(xt.ally.time or 0)/math.max(1,yt)),attack=wt.active_attack}
end
