V.IDOL={dmg={[0]=0.05,0.07,0.10,0.15},cost={[0]=0.05,0.10,0.15,0.20}}
function V.idolAt(Rt)
Rt=tonumber(Rt)or-1
if Rt<0 then
return 0,0
end
local St=V.IDOL
