if Rt<=Tt then
return St.dmg[Rt],St.cost[Rt]
end
return St.dmg[Tt]+(St.dmg[Tt]-St.dmg[Tt-1])*(Rt-Tt),math.min(0.5,St.cost[Tt]+(St.cost[Tt]-St.cost[Tt-1])*(Rt-Tt))
end
