function W.ldMod(tx)
if type(tx)~=GBe[2163]then
return nil
end
local ux={weak={},strong={},res={}}
for vx,xx in pairs(type(tx._weak_against)==GBe[2163]and tx._weak_against or type(tx.weak_against)==GBe[2163]and tx.weak_against or{})do
local yx=type(xx)==GBe[2163]and xx.damage_type or(type(xx)==GBe[1068]and xx)or nil
if yx then
ux.weak[yx]=type(xx)==GBe[2163]and W.weakAmp(xx.amplification)or 1.5
end
end
for zx,Ax in pairs(type(tx._strong_against)==GBe[2163]and tx._strong_against or type(tx.strong_against)==GBe[2163]and tx.strong_against or{})do
local Bx=type(Ax)==GBe[2163]and Ax.damage_type or(type(Ax)==GBe[1068]and Ax)or nil
local Cx,Dx=type(Ax)==GBe[2163]and tonumber(Ax.amplification),type(Ax)==GBe[2163]and tonumber(Ax.resistance)
if Bx then
if Dx then
ux.res[Bx]=100/(100+Dx)
elseif Cx and Cx<1 then
ux.res[Bx]=Cx
else
ux.strong[Bx]=true
end
end
end
return(next(ux.weak)or next(ux.strong)or next(ux.res))and ux or nil
end
