W._levelMod={}
function W.levelMod(Hx)
if Hx==nil then
return nil
end
if W._levelMod[Hx]~=nil then
return W._levelMod[Hx]or nil
end
W._levelMod[Hx]=false
local Ix=N.Levels[Hx]
local Jx=type(Ix)==GBe[2163]and N.Waves[Ix.waves or Hx]
local Kx=type(Jx)==GBe[2163]and Jx.initial_unit_configs
if type(Kx)~=GBe[2163]then
return nil
end
local Lx,Mx,Nx={},{},0
for Ox,Px in pairs(Kx)do
local Qx=type(Px)==GBe[2163]and type(Px.override_stats)==GBe[2163]and(Px.override_stats[1]or Px.override_stats[GBe[2609]])or nil
if type(Qx)==GBe[2163]then
local Rx=tonumber(Qx.health)or 20
Nx=Nx+Rx
table.insert(Lx,{hp=Rx,st=Qx})
for Sx in pairs(Qx)do
local Tx=tostring(Sx):match(GBe[2318])or tostring(Sx):match(GBe[2610])
if Tx then
Mx[Tx]=true
end
end
end
end
if not next(Mx)or Nx<=0 then
return nil
end
local Ux={weak={},strong={},res={}}
for Vx in pairs(Mx)do
local Wx=0
for Xx,Yx in ipairs(Lx)do
local Zx=(1+(tonumber(Yx.st[GBe[2454]..Vx])or 0))*100/(100+math.max(0,tonumber(Yx.st[GBe[2611]..Vx])or 0))
Wx=Wx+Yx.hp/math.max(0.05,Zx)
end
local _x=Nx/math.max(1,Wx)
if _x>1.02 then
Ux.weak[Vx]=_x
elseif _x<0.98 then
Ux.res[Vx]=_x
end
end
if not(next(Ux.weak)or next(Ux.res))then
return nil
end
W._levelMod[Hx]=Ux
return Ux
end
function W.dailyMod(ay,cy,dy)
