end
F.log(1,GBe[2677],string.format(GBe[2780],tI-oI(),(tonumber(((N.prof().capsule_pity_data or{})[mb.STAR]or{}).total_opens)or 0)))
ab.pickNote.skins=nil
elseif uI.open>0 then
