function W.score(zQ)
local AQ,BQ=((zQ.kind==GBe[2186]and zQ.rec.runs>0)or zQ.kind==GBe[2188]or zQ.kind==GBe[2623])and 1 or(zQ.kind==GBe[2189]and zQ.p0)or W.winP(zQ),W.minutes(zQ)
