Ccb[Ecb.uuid]=true
end
for Fcb,Gcb in pairs(ccb)do
if Gcb._equipped_relic then
Acb=Acb+1
if not Ccb[Fcb]and(not Bcb or not table.find(P.str.core or{},Fcb))then
Bcb=Gcb._equipped_relic
end
end
end
if Acb>=kb.MAX_RELICS and Bcb and not jcb(Bcb)then
return false
end
local Hcb=U.now()
F.request(GBe[3211],GBe[2700],zcb,{unit_uuid=ycb.e.uuid})
while U.now()-Hcb<4 and ycb.e.u._equipped_relic~=zcb do
task.wait(0.25)
end
task.wait(1.2)
if ycb.e.u._equipped_relic~=zcb then
F.log(1,GBe[3194],string.format(GBe[3215],(N.Items[(bcb.inventory:get_item_by_uuid(zcb)or{}).item_id]or{}).name or GBe[3216],V.name(ycb.e.id),hcb(Hcb)))
F.backoff(GBe[3211],300)
P.str.relicAt=0
return false
end
wcb=wcb+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
P.str.relicTeam=P.str.relicSig
P.str.relicNote=string.format(GBe[3217],Zbb)
kb.note(string.format(GBe[3218],wcb,Zbb))
