table.insert(Wcb,{kind=GBe[3220],uuid=cdb,name=fdb,gain=kdb,add=hdb,planned=ldb.planned,items=ldb.n,lvl0=mdb,lvl1=kb.level({unit_id=edb,xp=(tonumber(ddb.xp)or 0)+(ldb.planned>0 and ldb.planned or hdb)}),text=string.format(GBe[3221],fdb,U.fmt(hdb),ndb>mdb and string.format(GBe[3222],mdb,ndb)or string.format(GBe[3223],mdb),kdb)})
end
end
end
end
table.sort(Wcb,function(odb,pdb)
if odb.gain~=pdb.gain then
return odb.gain>pdb.gain
end
return odb.text<pdb.text
end)
for qdb in pairs(V._mult)do
