function kb.feedPlan(Wdb)
local Xdb=V.trait(Wdb)
local Ydb=Xdb==GBe[3226]and 1.5 or 1
local Zdb=math.max(0,kb.xpFor(Wdb.unit_id,kb.cap(Wdb))-(tonumber(Wdb.xp)or 0))
local _db,aeb,beb={},0,0
for ceb,deb in ipairs(kb.foodHeld())do
local eeb=deb.xp*Ydb
local feb=math.min(deb.n,math.floor((Zdb-aeb)/math.max(1,eeb)))
if feb>0 then
_db[deb.id]=feb
aeb=aeb+feb*eeb
beb=beb+feb
end
end
return{feed=_db,planned=aeb,n=beb}
end
function kb.run(geb)
local heb=N.session()
local ieb=heb and heb.collection:get_unit_by_uuid(geb.uuid)
if not ieb then
return
end
if geb.kind==GBe[3220]then
local jeb=kb.feedPlan(ieb)
local keb,leb,meb=jeb.feed,jeb.planned,jeb.n
if meb==0 then
P.str.feedNote=geb.name..GBe[3227]
return
end
local neb,oeb=tonumber(ieb.xp)or 0,kb.level(ieb)
local peb,qeb=F.request(GBe[3220],GBe[3228],geb.uuid,keb)
local reb=U.now()
while U.now()-reb<4 and(tonumber((heb.collection:get_unit_by_uuid(geb.uuid)or ieb).xp)or 0)<=neb do
task.wait(0.25)
end
local seb=heb.collection:get_unit_by_uuid(geb.uuid)or ieb
local teb=(tonumber(seb.xp)or 0)-neb
if teb>0 then
local ueb=kb.level(seb)
local veb=ueb>oeb and string.format(GBe[3222],oeb,ueb)or string.format(GBe[3223],oeb)
cb.add(string.format(GBe[3229],meb,geb.name),meb,GBe[3230],string.format(GBe[3231],U.fmt(teb),veb))
kb.note(string.format(GBe[3232],geb.name,meb,U.fmt(teb),veb,math.abs(teb-leb)>leb*0.1 and string.format(GBe[3233],U.fmt(leb))or GBe[1082]))
else
kb.note(string.format(GBe[3234],geb.name,tostring(peb and qeb or GBe[2707])))
F.backoff(GBe[3220],600)
end
end
end
