end
end
if ab.snipeWanted()then
return GBe[3243]..V.name(O.snipeUnit)..GBe[3244],GBe[3245]
end
if ab.snipeDue()then
return GBe[3246]..V.name(O.snipeUnit)..GBe[3247],GBe[3245]
end
if P.ownSwap then
return GBe[3248]..V.name(P.ownSwap.into)..GBe[3249],GBe[3250]
end
