table.insert(Xeb,Zeb)
end
end
end
local _eb=kb.nextAct(Xeb)
if _eb then
return _eb.text,_eb.kind
end
if O.teamRelics and(tonumber(P.str.noWork.relic)or 0)<=os.time()and(not Seb or not(O.autoTeam and O.play))then
local afb,bfb=kb.relicPlan()
