end
F.status(GBe[3255],GBe[3256]..tostring(efb))
if ffb==GBe[3252]then
local gfb,hfb=pcall(kb.relicsApply,true)
if not(gfb and hfb)then
P.str.noWork.relic=os.time()+1800
end
else
kb.tick()
end
dfb=dfb+1
task.wait(4)
end
if dfb>0 then
F.log(1,kb.LOG,string.format(GBe[3257],dfb,math.floor(U.now()-cfb)))
W._sigAt,W.lastScored=nil,nil
F.saveSoon()
end
