function kb.tick()
if not O.team then
P.str.next=GBe[3258]
return
end
if P.str.reequip then
kb.reequip()
end
local ifb
if ab.every(GBe[3259],60)or not P.str.acts then
ifb=kb.plan()
else
ifb=kb.acts
end
kb.acts=ifb or kb.acts or{}
local jfb=kb.nextAct(kb.acts)
if not jfb then
local kfb=kb.acts[1]
P.str.next=kfb and(kfb.text..GBe[3260]..tostring(kfb.blocked))or GBe[3261]
