end
local Vfb=string.format(GBe[3282],V.name(Cfb.from),V.name(Cfb.to),U.fmt(Cfb.scoreFrom or 0),U.fmt(Cfb.scoreTo or 0))
cb.add(GBe[3283]..Vfb,1,GBe[3284],(Dfb or GBe[3285])..(#Qfb>0 and(GBe[3286]..table.concat(Qfb,GBe[2284]))or GBe[1082]))
F.log(1,GBe[3287],Vfb..GBe[3288]..(Dfb or GBe[3285])..(#Qfb>0 and(GBe[3286]..table.concat(Qfb,GBe[2284]))or GBe[1082]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(Cfb.to)..GBe[3289]
end
F.log(1,GBe[3287],GBe[3290]..V.name(Cfb.from)..GBe[2862]..tostring(Lfb)..GBe[3291]..tostring(Mfb and Mfb.unit_id))
return false,GBe[3292]..tostring(Lfb)..GBe[2834]
