F.log(1,GBe[3402],string.format(GBe[3403],Vkb.label,V.name(Wkb.id),elb.out and(GBe[3404]..V.name(elb.out))or GBe[1082],elb.ok and string.format(GBe[3405],math.floor((ib.perRun(Vkb.key,Wkb.id)or 0)+0.5),Wkb.what,elb.minutes,elb.ownMin)or tostring(elb.why)))
