function eb.upgradeGain(sGb,tGb,uGb,vGb,wGb,xGb)
local yGb,zGb=tGb[uGb],tGb[uGb+1]
local AGb=(yGb.cd>0 and yGb.damage/yGb.cd or 0)
local BGb=(zGb.cd>0 and zGb.damage/zGb.cd or 0)*V.aoe(zGb.atk,zGb.range)/math.max(0.3,V.aoe(yGb.atk,yGb.range))
local CGb=AGb>0 and sGb*(BGb/AGb-1)or(xGb or 0)
local DGb=tGb[uGb+2]
if DGb and uGb+1<tGb.max and DGb.cd>0 and zGb.cd>0 and AGb>0 then
local EGb=sGb*((DGb.damage/DGb.cd)/AGb-1)
local FGb=vGb+DGb.cost*wGb
if EGb/FGb>CGb/vGb then
CGb=CGb+(EGb/FGb*vGb-CGb)*0.5
end
end
local GGb=(zGb.range or 0)>(yGb.range or 0)and(1+((zGb.range-yGb.range)/math.max(1,yGb.range)))or 1
return math.max(0,CGb)*GGb
end
function eb.dpsFor(HGb,IGb)
if IGb<=0 then
return 0
end
local JGb={}
for KGb,LGb in ipairs(HGb)do
if not LGb.farm and not LGb.grif and LGb.gain>0 then
table.insert(JGb,LGb)
end
end
table.sort(JGb,function(MGb,NGb)
return MGb.gain/MGb.cost>NGb.gain/NGb.cost
end)
local OGb,PGb=0,0
for QGb,RGb in ipairs(JGb)do
if IGb<=0 then
break
end
PGb=RGb.gain/RGb.cost
local SGb=math.min(1,IGb/RGb.cost)
OGb=OGb+RGb.gain*SGb
IGb=IGb-RGb.cost*SGb
end
return OGb+math.max(0,IGb)*PGb*0.7
end
function eb.shieldDps(TGb,UGb,VGb,WGb,XGb,YGb,ZGb)
if(WGb or 0)<=0 or(TGb or 0)<=0 or(XGb or 0)<=0 then
return TGb or 0
end
UGb,VGb,YGb=math.max(0.3,UGb or 2),math.max(1,VGb or 1),YGb or 1
local _Gb=TGb*YGb*UGb/VGb
return XGb*VGb/((WGb/math.max(1,ZGb or 1)+math.max(1,XGb/_Gb))*UGb)/YGb
end
function eb.shieldGain(aHb,bHb,cHb,dHb,eHb,fHb,gHb,hHb)
local iHb,jHb=V.attackInfo(bHb.atk,bHb.range),V.attackInfo(dHb.atk,dHb.range)
local kHb=eb.shieldDps(aHb,(tonumber(bHb.cd)or 2)*(gHb or 1),iHb.n,eHb,fHb,hHb,iHb.hits)
local lHb=eb.shieldDps(cHb,(tonumber(dHb.cd)or 2)*(gHb or 1),jHb.n,eHb,fHb,hHb,jHb.hits)
local mHb=math.max(0,((tonumber(dHb.range)or 0)-(tonumber(bHb.range)or 0))/math.max(1,tonumber(bHb.range)or 1))
return math.max(0,lHb-kHb)+kHb*mHb
end
function eb.shieldWork(nHb,oHb,pHb,qHb,rHb,sHb,tHb,uHb,vHb)
if(qHb or 0)<=0 then
return 0
end
local wHb=3*qHb*(rHb or 1)/math.max(1,sHb or 20)
if(pHb or 0)>=wHb then
return 0
end
return math.max(1,nHb or 1)*math.max(1,vHb or 1)/math.max(0.3,oHb or 2)*math.min(tHb or 0,uHb or 0)
end
function eb.holdGain(xHb,yHb,zHb,AHb)
if not xHb or(yHb or 0)<=0 then
return 0
end
local BHb,CHb=tonumber(xHb.stun)or 0,tonumber(xHb.slowTime)or 0
if BHb<=0 and CHb<=0 then
return 0
end
local DHb,EHb=BHb>0 and BHb or CHb,BHb>0 and 1 or(tonumber(xHb.slowPct)or 0.3)
local FHb=EHb*DHb/(DHb+(tonumber(xHb.ccCd)or 8))
local GHb=FHb/math.max(0.1,1-FHb)
return yHb*GHb*U.clamp(zHb or 0.5,0,1)*math.min(1,(tonumber(xHb.n)or 1)/2)/(1+(AHb or 0))
end
function eb.bleedGain(HHb,IHb,JHb,KHb)
if(HHb or 0)<=0 then
return 0
end
local LHb=IHb or 0
for MHb,NHb in ipairs(JHb or{})do
LHb=math.max(LHb,(tonumber(NHb.hp)or 0)*0.5)
end
return HHb*LHb*(KHb and 0.5 or 1)
end
function eb.bleedShare(OHb,PHb,QHb,RHb)
if OHb<=0 or not PHb then
return 0
end
if RHb then
return PHb==0 and OHb or OHb/(PHb+1)
end
return QHb<PHb and OHb/(PHb-QHb)or 0
end
function eb.keepsUp(SHb,THb,UHb,VHb,WHb)
local XHb=SHb.coming
if not(XHb and#XHb>0 and SHb.waveSec)then
return true
end
local YHb=SHb.eff or 1
local ZHb=SHb.money-UHb
local _Hb=(SHb.teamDps or 0)*(SHb.shieldK or 1)+(VHb or 0)*YHb+eb.dpsFor(THb,math.max(0,ZHb))*YHb
local aIb=(SHb.farmNow or 0)+(WHb or 0)
local bIb=(SHb.roadSec or 130)*U.clamp(SHb.cover or 0.6,0.1,1)
local cIb=SHb.hpAlive or 0
for dIb,eIb in ipairs(XHb)do
cIb=math.max(0,cIb+eIb.hp-_Hb*SHb.waveSec)
local fIb=_Hb*bIb
if cIb>fIb then
return false,dIb,fIb/math.max(1,cIb)
end
if dIb< #XHb then
_Hb=_Hb+eb.dpsFor(THb,(eIb.reward or 0)+aIb)*YHb*(0.85^dIb)
end
end
return true
end
function eb.decide(gIb,hIb)
local iIb=U.clamp(hIb.cover or 0.6,0.1,1)
local jIb=math.max(O.clearSec,0.7*(hIb.roadSec or 50)*iIb)
local kIb=(hIb.clearSec or 0)>jIb
hIb.piling=hIb.piling and kIb
local lIb=hIb.attackers>0 and hIb.pressure<math.min(O.safeReach,iIb*0.75)and not hIb.piling and not kIb
local mIb=hIb.pressure>=math.min(O.dangerReach,iIb*0.9)or(hIb.piling and hIb.enemies>=18)
local nIb,oIb
for pIb,qIb in ipairs(gIb)do
if qIb.farm then
if O.farmUnits and qIb.gain>0 then
qIb.payback=qIb.cost/qIb.gain
if hIb.left-1>=qIb.payback+(hIb.farmSpare or O.farmSpare)and(not nIb or qIb.payback<nIb.payback)then
nIb=qIb
end
end
else
qIb.ratio=qIb.gain/math.max(1,qIb.cost)
if not oIb or qIb.ratio>oIb.ratio then
oIb=qIb
end
end
end
if hIb.leak and hIb.attackers>0 then
local rIb
for sIb,tIb in ipairs(gIb)do
local uIb=not hIb.airLeak or(tIb.e and bb.cardAir(tIb.e.id))
if tIb.place and not tIb.farm and not tIb.idol and not tIb.grif and uIb and tIb.cost<=hIb.money and not(tIb.e and V.allyBuff(tIb.e.id))and(not rIb or tIb.gain>rIb.gain)then
rIb=tIb
