if rIb then
return rIb,string.format(GBe[3896],math.floor(hIb.leak*100))
end
end
local vIb=hIb.future<hIb.wantLeft*1.1
local wIb,xIb,yIb=true,nil,nil
if nIb then
wIb,xIb,yIb=eb.keepsUp(hIb,gIb,nIb.cost,0,nIb.gain)
end
local zIb=hIb.coming and not eb.keepsUp(hIb,gIb,0,0,0)
local AIb=false
if bb.random and nIb and not mIb and hIb.attackers>=2 and nIb.payback<=hIb.left/3 then
local BIb=0
for CIb,DIb in ipairs(bb.mine or{})do
