for oic in pairs(hic.types or{})do
if nic[oic]then
jic=jic+1
break
end
end
end
end
table.sort(iic)
table.insert(gic,string.format(GBe[4063],#iic>0 and table.concat(iic,GBe[2444])or GBe[4064],jic))
end
if V.BLESS.by[fic]and#_hc>0 then
table.insert(gic,GBe[4065]..table.concat(_hc,GBe[2284]))
end
if V.SUMMONER[fic]then
table.insert(gic,GBe[4066])
elseif V.DRONES[fic]then
table.insert(gic,GBe[4067])
end
local pic,qic=pcall(V.bleeds,fic)
if(Uhc and Uhc.regen or 0)>0 and pic and qic then
table.insert(gic,string.format(GBe[4068],qic))
end
local ric,sic=pcall(bb.cardAir,fic)
if cic and ric and sic then
