end
if Yhc.strong and Yhc.strong[uic]then
table.insert(gic,string.format(GBe[4073],Whc(uic)))
end
if#gic==0 then
table.insert(gic,GBe[4074])
end
local zic,Aic,Bic=pcall(V.mapNudge,fic,Uhc and Uhc.map,Uhc and Uhc.mapSig)
local Cic=zic and type(Bic)==GBe[2163]and(tonumber(Bic.n)or 0)or 0
