end
P.searchX[tostring(Dic)]={at=os.time(),label=tostring(Eic),team=Pic,ids=Qic,mine= #Ric>0 and Ric or nil,swapped=Iic and true or nil,map=Fic and Fic.map or nil,against=Lic and Mic or{GBe[2406]},how=Hic or{},why=Nic and Oic or{GBe[2406]},stats=type(Kic)==GBe[2163]and Kic or nil}
