local ljc=U.unjson(hjc[kjc])
local mjc=type(ljc)==GBe[2163]and type(ljc.result)==GBe[2163]and ljc.result.shares
if type(mjc)==GBe[2163]then
for njc,ojc in pairs(mjc)do
