djc[njc],ejc[njc]=(djc[njc]or 0)+tonumber(ojc),(ejc[njc]or 0)+1
end
end
end
end
end
end)
for pjc,qjc in pairs(djc)do
cjc[pjc]=qjc/ejc[pjc]
end
gb._rsh[tostring(_ic)]={t=U.now(),v=cjc}
return cjc
end
