function jb.pick(Hoc)
local Ioc,Joc=jb.curses(Hoc),jb.lives(Hoc)
local Koc=jb.res(Hoc)
local Loc=jb.rooms(Hoc)
local Moc={}
for Noc,Ooc in ipairs(Loc)do
table.insert(Moc,tostring(Ooc.r._r))
end
local Poc=table.concat(Moc,GBe[3035])..string.format(GBe[4185],Joc,Koc,Ioc,W.teamSig())
if jb._pick and jb._pick.sig==Poc then
return jb._pick.x
end
local Qoc,Roc,Soc,Toc
for Uoc,Voc in ipairs(Loc)do
local Woc=jb.roomValue(Voc,Koc)
local Xoc,Yoc
for Zoc,_oc in ipairs(jb.after(Hoc,Voc.choice))do
local apc=jb.roomValue(_oc,Koc)
if not Xoc or apc>Xoc then
Xoc,Yoc=apc,_oc
end
end
local bpc,cpc=jb.winP(Voc)
local dpc=cpc~=nil and cpc.won==false
local epc=Joc>=3 and 1 or(Joc==2 and 2 or 6)
local fpc=1-(1-bpc)^math.max(1,Joc)
Voc.oldScore=fpc*(Woc+0.6*(Xoc or 0))-(1-bpc)*epc
if dpc then
bpc=math.min(bpc,jb.lossWin())
fpc=bpc
epc=epc*2
end
Voc.p,Voc.sim,Voc.value,Voc.nextValue,Voc.nextRoom,Voc.simLost=bpc,cpc,Woc,Xoc or 0,Yoc,dpc or nil
Voc.score=fpc*(Woc+0.6*(Xoc or 0))-(1-bpc)*epc
local gpc,hpc,ipc=pcall(jb.curseGate,Voc,Hoc)
if gpc and not hpc then
Voc.blocked=ipc
end
if not Voc.blocked then
if not Qoc or Voc.score>Qoc.score then
Qoc=Voc
end
if dpc then
if not Toc or Voc.score>Toc.score then
Toc=Voc
end
elseif not Soc or Voc.score>Soc.score then
Soc=Voc
end
end
if not Roc or Voc.score>Roc.score then
Roc=Voc
end
end
if Qoc and Qoc.simLost and Soc then
F.log(1,GBe[4186],string.format(GBe[4187],jb.roomName(Qoc),tostring(Qoc.sim and Qoc.sim.margin or GBe[2406]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Soc)))
elseif Qoc and Toc and Toc~=Qoc and Toc.oldScore>Qoc.score then
F.log(1,GBe[4186],string.format(GBe[4188],jb.roomName(Toc),tostring(Toc.sim and Toc.sim.margin or GBe[2406]),jb.roomName(Qoc)))
end
Qoc=Qoc or Roc
jb._pick={sig=Poc,x=Qoc,rooms=Loc}
return Qoc
end
