function jb.cleared(rpc)
return math.max(1,(jb.depth(rpc)or(jb.ROOMS+1))-1)
end
function jb.state(spc)
if spc._dead then
return GBe[2937]
end
local tpc=jb.screens(spc)[1]
if spc._finished and(not tpc or tpc.t==jb.T.OPEN)then
return GBe[4190]
end
if tpc then
if tpc.t==jb.T.SHOP then
return GBe[3254],tpc
end
if tpc.t==jb.T.OPEN then
return GBe[4191],tpc
end
if tpc.t==jb.T.SHRINE then
return GBe[4143],tpc
end
return GBe[4192],tpc
end
return GBe[4193]
end
function jb.logState(upc,vpc)
local wpc={}
for xpc,ypc in pairs(upc)do
if not jb.KNOWN[xpc]and not(type(ypc)==GBe[2163]and next(ypc)==nil)then
table.insert(wpc,tostring(xpc))
end
end
table.sort(wpc)
local zpc={}
for Apc,Bpc in ipairs(jb.screens(upc))do
table.insert(zpc,tostring(Bpc.t))
end
local Cpc=table.concat(wpc,GBe[3035])..(#zpc>0 and(GBe[2296]..table.concat(zpc,GBe[3035]))or GBe[1082])
if Cpc==GBe[1082]or P.dg.seen[Cpc]then
return
end
P.dg.seen[Cpc]=os.time()
local Dpc={}
for Epc,Fpc in ipairs(wpc)do
local Gpc=upc[Fpc]
table.insert(Dpc,Fpc..GBe[2839]..(type(Gpc)==GBe[2163]and U.json(U.plain(Gpc)):sub(1,500)or tostring(Gpc)))
end
F.log(1,GBe[4186],GBe[4194]..tostring(vpc)..GBe[4195]..table.concat(Dpc,GBe[2546]))
F.saveSoon()
end
function jb.note(Hpc)
F.log(1,GBe[4186],Hpc)
table.insert(P.dg.log,1,{at=os.time(),msg=Hpc})
while#P.dg.log>15 do
table.remove(P.dg.log)
end
F.saveSoon()
end
function jb.offers(Ipc,Jpc)
local Kpc={}
if type(Ipc)~=GBe[2163]then
return Kpc
end
for Lpc,Mpc in pairs(Ipc)do
local Npc,Opc
if type(Mpc)==GBe[2163]then
Npc=Mpc.id or Mpc.item_id or Mpc.item
Opc=tonumber(Mpc.cost)or tonumber(Mpc.price)
elseif type(Mpc)==GBe[1068]then
Npc=Mpc
elseif jb.item(Lpc)then
Npc=Lpc
Opc=tonumber(Mpc)
end
if type(Npc)==GBe[1068]and jb.item(Npc)then
table.insert(Kpc,{key=Lpc,id=Npc,cost=Opc or tonumber(jb.item(Npc).cost)or 0,bought=type(Mpc)==GBe[2163]and(Mpc.bought or Mpc.sold or Mpc.purchased)or nil})
end
end
if#Kpc==0 and not Jpc then
for Ppc,Qpc in pairs(Ipc)do
if type(Qpc)==GBe[2163]then
Kpc=jb.offers(Qpc,true)
if#Kpc>0 then
break
end
end
end
end
return Kpc
end
function jb.buy(Rpc)
local Spc=jb.res(jb.data())
local Tpc={}
if P.dg.buyArg==GBe[2548]then
Tpc={Rpc.id,Rpc.key}
else
Tpc={Rpc.key,Rpc.id}
end
if Tpc[1]==Tpc[2]then
Tpc[2]=nil
end
for Upc,Vpc in ipairs(Tpc)do
local Wpc,Xpc=F.request(GBe[4196],GBe[3812],Vpc)
local Ypc=U.now()
while U.now()-Ypc<3 and jb.res(jb.data())>=Spc do
task.wait(0.25)
end
if jb.res(jb.data())<Spc then
P.dg.buyArg=(Vpc==Rpc.id and Rpc.id~=Rpc.key)and GBe[2548]or GBe[4197]
return true
end
if not Wpc then
break
end
end
return false
end
function jb.shopAhead(Zpc)
for _pc,aqc in ipairs(jb.rooms(Zpc))do
if aqc.tags[jb.T.SHOP]then
return true
end
for bqc,cqc in ipairs(jb.after(Zpc,aqc.choice))do
if cqc.tags[jb.T.SHOP]then
return true
end
end
end
return false
end
jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(dqc,eqc)
local fqc=jb.cleared(dqc)
local gqc=jb.res(dqc)
local hqc=1+0.1*(jb.items(dqc)._curse_shop or 0)
local iqc=jb.shopAhead(dqc)and math.ceil(jb.LUCK_RESERVE*hqc)or 0
local jqc={}
local kqc,lqc={},0
for mqc,nqc in ipairs(jb.offers(eqc and eqc.data))do
nqc.cost=math.ceil(nqc.cost*hqc)
table.insert(kqc,tostring(jb.item(nqc.id).name or nqc.id))
if not nqc.bought and not jb.isCurse(nqc.id)then
nqc.luck=tonumber(jb.item(nqc.id).luck_increase)~=nil
nqc.v=jb.itemValue(nqc.id,dqc)
if not nqc.luck and nqc.v/math.max(1,nqc.cost)<jb.MIN_WORTH then
lqc=lqc+1
elseif nqc.v>0 and(nqc.luck or fqc>=10 or nqc.v/math.max(1,nqc.cost)>=jb.TOP_WORTH)then
table.insert(jqc,nqc)
end
end
end
table.sort(jqc,function(oqc,pqc)
if oqc.luck~=pqc.luck then
return oqc.luck
end
return oqc.v/math.max(1,oqc.cost)>pqc.v/math.max(1,pqc.cost)
end)
local qqc,rqc,sqc={},0,0
for tqc,uqc in ipairs(jqc)do
if uqc.cost<=gqc-(uqc.luck and 0 or iqc)then
if jb.buy(uqc)then
gqc=jb.res(jb.data())
table.insert(qqc,string.format(GBe[4198],tostring(jb.item(uqc.id).name or uqc.id),uqc.cost))
end
elseif uqc.cost<=gqc then
sqc=sqc+1
else
rqc=rqc+1
end
end
jb.note(string.format(GBe[4199],fqc,#kqc>0 and table.concat(kqc,GBe[2284])or GBe[4200],#qqc>0 and(GBe[4201]..table.concat(qqc,GBe[2284]))or(fqc<10 and GBe[4202]or(sqc>0 and GBe[4203]or GBe[4204])),gqc,rqc>0 and string.format(GBe[4205],rqc)or GBe[1082],sqc>0 and string.format(GBe[4206],sqc,iqc)or GBe[1082],lqc>0 and string.format(GBe[4207],lqc)or GBe[1082]))
F.request(GBe[4208],GBe[4209])
end
function jb.shrine(vqc,wqc)
local xqc=jb.offers(wqc and wqc.data)
local yqc,zqc=0,{}
local Aqc
for Bqc,Cqc in ipairs(xqc)do
local Dqc=jb.item(Cqc.id)
table.insert(zqc,tostring(Dqc and Dqc.name or Cqc.id))
if jb.isCurse(Cqc.id)then
local Eqc,Fqc,Gqc=pcall(jb.curseOk,Cqc.id,vqc,jb.cleared(vqc)+1,nil,jb.rooms(vqc))
if Eqc and not Fqc then
Aqc=Gqc
end
else
yqc=yqc+jb.itemValue(Cqc.id,vqc)
end
end
local Hqc= #xqc>0 and yqc>0 and not Aqc
if Hqc then
F.request(GBe[4210],GBe[3816])
else
F.request(GBe[4208],GBe[4209])
end
jb.note(string.format(GBe[4211],#zqc>0 and table.concat(zqc,GBe[2284])or GBe[4200],Hqc and GBe[4212]or(Aqc and(GBe[4213]..Aqc)or GBe[4214])))
end
function jb.wallet()
local Iqc=N.session()and N.session().profile_data or{}
local Jqc=Iqc.inventory or{}
local Kqc={gems=tonumber(N.cur(GBe[2233]))or 0,gold=tonumber(N.cur(GBe[2235]))or 0,items={},units={},unique=0}
for Lqc,Mqc in pairs(Jqc.normal_items or{})do
Kqc.items[Lqc]=tonumber(Mqc)or 0
end
for Nqc,Oqc in pairs(Iqc.collection and Iqc.collection.owned_units or{})do
Kqc.units[Nqc]=Oqc.unit_id
end
for Pqc in pairs(Jqc.unique_items or{})do
Kqc.unique=Kqc.unique+1
end
return Kqc
end
function jb.walletDiff(Qqc,Rqc)
local Sqc={}
if Rqc.gems~=Qqc.gems then
table.insert(Sqc,string.format(GBe[4215],Rqc.gems-Qqc.gems))
end
if Rqc.gold~=Qqc.gold then
table.insert(Sqc,string.format(GBe[4216],Rqc.gold-Qqc.gold))
end
for Tqc,Uqc in pairs(Rqc.items)do
if Uqc~=(Qqc.items[Tqc]or 0)then
table.insert(Sqc,string.format(GBe[4217],Uqc-(Qqc.items[Tqc]or 0),tostring(Tqc)))
end
end
for Vqc,Wqc in pairs(Rqc.units)do
if not Qqc.units[Vqc]then
table.insert(Sqc,GBe[4218]..V.name(Wqc))
end
end
if Rqc.unique~=Qqc.unique then
table.insert(Sqc,string.format(GBe[4219],Rqc.unique-Qqc.unique))
end
return#Sqc>0 and table.concat(Sqc,GBe[2284])or GBe[4220]
end
function jb.openChests(Xqc,Yqc)
local Zqc,_qc,arc=jb.res(Xqc)
local brc=jb.lives(Xqc)
local crc=jb.cleared(Xqc)
if not(Yqc or crc>=jb.ROOMS or brc<=1)then
jb.note(string.format(GBe[4221],crc,_qc,arc,jb.luck(Xqc)))
F.request(GBe[4208],GBe[4209])
return
end
local drc,erc,frc=0,0,0
local grc=tonumber(N.cur(GBe[2233]))or 0
local hrc=jb.wallet()
for irc=1,_qc+arc+4 do
local jrc,krc,lrc=jb.res(jb.data())
if krc+lrc<=0 or frc>=2 then
break
end
local mrc,nrc
if krc>0 then
mrc,nrc=F.request(GBe[4222],GBe[3815])
else
mrc,nrc=F.request(GBe[4222],GBe[3815],true)
end
if mrc and nrc~=nil then
F.log(1,GBe[4186],GBe[4223]..(type(nrc)==GBe[2163]and U.json(U.plain(nrc)):sub(1,300)or tostring(nrc)))
end
local orc=U.now()
while U.now()-orc<4 do
local prc,qrc,rrc=jb.res(jb.data())
if qrc<krc or rrc<lrc then
break
end
task.wait(0.25)
end
local trc,urc,vrc=jb.res(jb.data())
if urc<krc then
drc=drc+(krc-urc)
frc=0
elseif vrc<lrc then
erc=erc+(lrc-vrc)
frc=0
else
frc=frc+1
end
task.wait(1)
if urc<krc or vrc<lrc then
local wrc=jb.wallet()
local xrc=jb.walletDiff(hrc,wrc)
F.log(1,GBe[4186],(vrc<lrc and GBe[4224]or GBe[4223])..xrc)
P.dg.pay=P.dg.pay or{}
local yrc={}
for zrc,Arc in pairs(wrc.items)do
if Arc~=(hrc.items[zrc]or 0)then
yrc[zrc]=Arc-(hrc.items[zrc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=vrc<lrc,gems=wrc.gems-hrc.gems,luck=jb.luck(Xqc),paid=xrc,items=yrc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
hrc=wrc
end
end
jb.note(string.format(GBe[4225],drc,erc,Yqc and GBe[4226]or(brc<=1 and GBe[4227]or GBe[4228]),jb.luck(Xqc),(tonumber(N.cur(GBe[2233]))or 0)-grc))
local Brc,Crc,Drc=jb.res(jb.data())
if(Yqc or crc>=jb.ROOMS)and Crc+Drc>0 then
jb.note(string.format(GBe[4229],Crc,Drc))
W.rec(GBe[2892]).restUntil=os.time()+1800
return GBe[4230]
end
if not Yqc then
F.request(GBe[4208],GBe[4209])
end
end
function jb.act(Erc)
local Frc,Grc=jb.state(Erc)
jb.logState(Erc,Frc)
if Frc==GBe[4193]then
return false
end
if Frc==GBe[4192]then
jb.note(string.format(GBe[4231],tostring(Grc and Grc.t)))
F.request(GBe[4208],GBe[4209])
return true
end
if Frc==GBe[2937]then
F.request(GBe[4232],GBe[3813])
jb.note(GBe[4233])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
elseif Frc==GBe[4190]then
if jb.openChests(Erc,true)==GBe[4230]then
return GBe[4230]
end
F.request(GBe[4208],GBe[4209])
local Hrc,Irc,Jrc=jb.res(jb.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=jb.ROOMS,items=U.count(jb.items(Erc)),left=Irc+Jrc})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
jb.note(GBe[4234])
