function jb.launch(Krc)
local Lrc=jb.data()
if not Lrc then
F.backoff(GBe[3624],30)
return false
end
if not Lrc._started then
if not(O.dungeonStart or O.onlyDungeons)then
return false
end
local Mrc,Nrc=F.request(GBe[4235],GBe[3817])
task.wait(2.5)
Lrc=jb.data()
if not(Mrc and Lrc and Lrc._started)then
F.log(1,GBe[4186],GBe[4236]..tostring(Nrc)..GBe[4237])
W.rec(GBe[2892]).restUntil=os.time()+1800
F.backoff(GBe[3624],10)
