gb.memoOn()
local ksc=jb.ways(isc)
local lsc=type(P.dg.styles)==GBe[2163]and P.dg.styles[tostring(Vrc.r._r)]or nil
local function msc(nsc,osc)
local psc=gb.sig(nsc)
local qsc=type(P.dg.teams)==GBe[2163]and P.dg.teams[psc]or{}
local rsc=type(P.dg.lost)==GBe[2163]and P.dg.lost[tostring(Vrc.r._r)]and P.dg.lost[tostring(Vrc.r._r)][psc]or 0
local ssc=type(P.dg.bailed)==GBe[2163]and type(P.dg.bailed[tostring(Vrc.r._r)])==GBe[2163]and tonumber(P.dg.bailed[tostring(Vrc.r._r)][psc])or 0
rsc=rsc+ssc
