xsc=math.min(xsc,1)
end
xsc=xsc-3*rsc
local ysc=lsc and type(lsc.lost)==GBe[2163]and lsc.lost[osc.style]or nil
if type(ysc)==GBe[2163]and ysc.sig==psc then
xsc=xsc-3
end
return{score=tsc+xsc,wins=tsc,atOne=usc,reach=vsc,far=wsc,lostHere=rsc,left=ssc,w=tonumber(qsc.w)or 0,l=tonumber(qsc.l)or 0,style=osc.style}
