function jb.roomLearn(Luc)
if Luc or bb.kind~=GBe[2189]or bb.roomLearned then
return
end
local Muc=P.dg.room
local Nuc,Ouc=bb.pred,bb.calRun
if type(Muc)~=GBe[2163]or Muc.seed==nil or type(Nuc)~=GBe[2163]or not Nuc.won or type(Ouc)~=GBe[2163]then
return
end
local function Puc(Quc,Ruc)
return type(Quc)==GBe[2163]and tonumber(Quc[Ruc]or Quc[tostring(Ruc)])or nil
end
