for Tuc=2,bb.wave()do
local Uuc,Vuc=Puc(Ouc.alive,Tuc),Puc(Nuc.aliveAt,Tuc)
if Uuc and Vuc and Uuc>0 and Vuc>0 then
table.insert(Suc,Uuc/Vuc)
end
end
if#Suc<3 then
