table.insert(_uc,{s=avc,at=type(bvc)==GBe[2163]and tonumber(bvc.at)or 0})
end
table.sort(_uc,function(cvc,dvc)
return cvc.at>dvc.at
end)
for evc=31,#_uc do
P.dg.roomK[_uc[evc].s]=nil
end
F.log(1,GBe[4186],string.format(GBe[4299],tostring(Muc.d),Wuc,Zuc))
end
