function bb.buildPath()
bb.samples={}
local Ivc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Ivc then
return
end
for Jvc,Kvc in pairs(Ivc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Jvc.Name])then
local Lvc={}
for Mvc,Nvc in ipairs(Kvc.points or{})do
table.insert(Lvc,Nvc.part.Position)
end
local Ovc=0
for Pvc=2,#Lvc do
Ovc=Ovc+(Lvc[Pvc]-Lvc[Pvc-1]).Magnitude
end
local Qvc=0
for Rvc=2,#Lvc do
local Svc,Tvc=Lvc[Rvc-1],Lvc[Rvc]
local Uvc=(Tvc-Svc).Magnitude
local Vvc=math.max(1,math.floor(Uvc/2))
for Wvc=0,Vvc-1 do
local Xvc=Svc:Lerp(Tvc,Wvc/Vvc)
table.insert(bb.samples,{pos=Xvc,prog=(Qvc+Uvc*Wvc/Vvc)/math.max(1,Ovc),lane=Jvc.Name})
end
Qvc=Qvc+Uvc
end
if Lvc[#Lvc]then
table.insert(bb.samples,{pos=Lvc[#Lvc],prog=1,lane=Jvc.Name})
end
end
end
pcall(bb.readHidden,Ivc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Yvc=tonumber(bb.ld and bb.ld._portal_lanes)
local Zvc=gb.laneList(bb.samples)
if Yvc and Yvc>=1 and Zvc and#Zvc>Yvc then
bb.laneWant=Yvc
end
bb.laneTotal=Zvc and#Zvc or 1
bb.countLanes()
end
function bb.readHidden(_vc)
local awc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(awc)~=GBe[2163]or not next(awc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local bwc
for cwc,dwc in pairs(_vc)do
if awc[cwc.Name]and type(dwc.points)==GBe[2163]and#dwc.points>=2 then
local ewc={}
for fwc,gwc in ipairs(dwc.points)do
ewc[fwc]=U.flat(gwc.part.Position)
end
local hwc={}
for iwc,jwc in ipairs(bb.samples)do
local kwc=tostring(jwc.lane)
hwc[kwc]=hwc[kwc]or{}
table.insert(hwc[kwc],jwc)
end
local lwc,mwc
for nwc,owc in pairs(hwc)do
local pwc=0
for qwc=1,#ewc,math.max(1,math.floor(#ewc/20))do
local rwc=math.huge
for swc,twc in ipairs(owc)do
local uwc=(U.flat(twc.pos)-ewc[qwc]).Magnitude
if uwc<rwc then
rwc=uwc
end
end
pwc=pwc+rwc
end
if not mwc or pwc<mwc then
lwc,mwc=nwc,pwc
end
end
local vwc,wwc,xwc,ywc,zwc,Awc={},nil,nil,nil,0,0
for Bwc,Cwc in ipairs(ewc)do
local Dwc,Ewc=nil,math.huge
for Fwc,Gwc in ipairs(hwc[lwc])do
local Hwc=(U.flat(Gwc.pos)-Cwc).Magnitude
if Hwc<Ewc then
Ewc,Dwc=Hwc,Gwc.prog
end
end
Awc=math.max(Awc,Ewc)
if xwc then
local Iwc=Dwc-xwc
local Jwc=(Iwc>0.002 and 1)or(Iwc< -0.002 and-1)or ywc
if ywc and Jwc and Jwc~=ywc then
table.insert(vwc,math.floor(xwc*1000+0.5)/1000)
end
ywc,zwc=Jwc or ywc,zwc+math.abs(Iwc)
else
wwc=Dwc
end
xwc=Dwc
if Bwc%50==0 then
task.wait()
end
end
if xwc and Awc<=8 then
table.insert(vwc,math.floor(xwc*1000+0.5)/1000)
bwc=bwc or{}
bwc[cwc.Name]={from=math.floor((wwc or 0)*1000+0.5)/1000,len=math.floor(zwc*1000+0.5)/1000,turns=vwc,road=lwc}
end
end
end
if not bwc then
return
end
local Kwc=bb.ld.map
P.maps[Kwc]=P.maps[Kwc]or{}
local Lwc=P.maps[Kwc].hidden
P.maps[Kwc].hidden=bwc
if type(Lwc)~=GBe[2163]then
for Mwc,Nwc in pairs(bwc)do
F.log(1,GBe[2841],string.format(GBe[4315],Mwc,Nwc.len,tostring(Nwc.road),math.floor((#Nwc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local Owc,Pwc,Qwc={},0,0
for Rwc,Swc in ipairs(bb.samples)do
local Twc=tostring(Swc.lane)
if not Owc[Twc]then
Pwc=Pwc+1
end
Owc[Twc]=(Owc[Twc]or 0)+1
Qwc=Qwc+1
end
bb.laneCount={n=Pwc,by=Owc,avg=Pwc>0 and Qwc/Pwc or 1}
if Pwc>=2 then
local Uwc,Vwc=pcall(gb.laneSep,bb.samples)
local Wwc=P.maps[bb.mapKey()]
if Uwc and Vwc and type(Wwc)==GBe[2163]then
Wwc.sep=Vwc
end
end
