function bb.validOpen(fTc,gTc)
local hTc=N.PC.raycast(fTc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not hTc then
return nil
end
if not N.PC.is_valid_raycast_hit(hTc.Instance,gTc)then
return nil
end
local iTc=hTc.Position
if bb.blockedSpot(iTc)then
return nil
end
local jTc=(tonumber(gTc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(jTc*2,2.5,jTc*2)
bb.probe.CFrame=CFrame.new(iTc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return iTc
end
