function bb.layoutAdd(UUc,VUc,WUc,XUc,YUc)
UUc.runs,UUc.wins=(tonumber(UUc.runs)or 0)+1,(tonumber(UUc.wins)or 0)+(VUc and 1 or 0)
UUc.sec,UUc.wave=type(UUc.sec)==GBe[2163]and UUc.sec or{},type(UUc.wave)==GBe[2163]and UUc.wave or{}
if VUc and tonumber(WUc)then
table.insert(UUc.sec,math.floor(WUc+0.5))
end
table.insert(UUc.wave,tonumber(XUc)or 0)
if tonumber(YUc)then
UUc.kills=type(UUc.kills)==GBe[2163]and UUc.kills or{}
table.insert(UUc.kills,math.floor(tonumber(YUc)))
while#UUc.kills>bb.LAYOUT_KEEP do
table.remove(UUc.kills,1)
end
end
while#UUc.sec>bb.LAYOUT_KEEP do
table.remove(UUc.sec,1)
end
while#UUc.wave>bb.LAYOUT_KEEP do
table.remove(UUc.wave,1)
end
