function bb.layoutJudge(ZUc,_Uc,aVc,bVc,cVc)
cVc=cVc or GBe[4516]
local dVc,eVc=tonumber(ZUc and ZUc.runs)or 0,tonumber(_Uc and _Uc.runs)or 0
