end
if bVc and type(ZUc.kills)==GBe[2163]and type(_Uc.kills)==GBe[2163]and#ZUc.kills>=1 and#_Uc.kills>=bb.LAYOUT_CONTROL then
local fVc,gVc=bb.labMedian(ZUc.kills),bb.labMedian(_Uc.kills)
if fVc and gVc and fVc<gVc*0.97 and(#ZUc.kills>=2 or fVc<gVc*0.85)then
