if not aVc and iVc>=0.5 then
if hVc+0.25<iVc and(dVc>=2 or(hVc==0 and iVc>=0.9 and eVc>=3))then
return string.format(GBe[4518],tonumber(ZUc.wins)or 0,dVc,dVc==1 and GBe[1082]or GBe[2009],tonumber(_Uc.wins)or 0,eVc,cVc)
end
local jVc,kVc=bb.labMedian(ZUc.sec),bb.labMedian(_Uc.sec)
if jVc and kVc and jVc>kVc*1.10 and(#ZUc.sec>=2 or jVc>kVc*1.25)then
