bb.layoutAdd(yVc,nVc,oVc,rVc,vVc)
local zVc=bb.bookFor(pVc)
local AVc=zVc and type(zVc.real)==GBe[2163]and(tonumber(zVc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local BVc=AVc and zVc.real or sVc.own
local CVc=bb.layoutJudge(yVc,BVc,tVc,uVc,AVc and GBe[4522]or nil)
if CVc then
yVc.aside,yVc.why=os.time(),CVc
