bb.CONTROL_WORDS={GBe[4529],GBe[4530],GBe[4531],GBe[4532]}
function bb.controlSpot(IVc,JVc)
if not bb.killZone()then
return nil
end
local KVc=gb.holds
if not KVc(IVc.id)or V.toggleOf(IVc.id)then
return nil
end
local LVc,MVc,NVc,OVc=1,0,0,{}
local PVc=bb.hurtSamples()
for QVc,RVc in ipairs(bb.mine or{})do
local SVc=RVc._stats
local TVc=SVc.id.Value
if SVc:FindFirstChild(GBe[2423])and not V.isFarm(TVc)and not V.allyBuff(TVc)then
local UVc,VVc=U.flat(RVc:GetPivot().Position),SVc.range.Value
if KVc(TVc)and not V.toggleOf(TVc)then
NVc=NVc+1
table.insert(OVc,{p=UVc,r=VVc})
else
for WVc,XVc in ipairs(PVc)do
if(U.flat(XVc.pos)-UVc).Magnitude<=VVc then
LVc,MVc=math.min(LVc,XVc.prog),math.max(MVc,XVc.prog)
end
end
end
end
end
if MVc<=LVc then
LVc,MVc=0.75,0.98
end
local YVc=(JVc or NVc)+1
local ZVc=({LVc,MVc,(LVc+MVc)/2,LVc-(MVc-LVc)/2})[YVc]
if not ZVc then
return nil
end
local _Vc=V.range(IVc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local aWc={}
for bWc,cWc in ipairs(bb.cands)do
local dWc,eWc,fWc=U.flat(cWc),0,0
for gWc,hWc in ipairs(PVc)do
if(U.flat(hWc.pos)-dWc).Magnitude<=_Vc then
fWc=fWc+1
if math.abs(hWc.prog-ZVc)<=0.05 then
eWc=eWc+1
local iWc=U.flat(hWc.pos)
for jWc,kWc in ipairs(OVc)do
if(iWc-kWc.p).Magnitude<=kWc.r then
eWc=eWc-0.5
break
end
end
end
end
end
if eWc>0 then
table.insert(aWc,{pos=cWc,sc=eWc,cov=fWc})
end
if bWc%60==0 then
task.wait()
end
end
table.sort(aWc,function(lWc,mWc)
return lWc.sc>mWc.sc
end)
for nWc,oWc in ipairs(aWc)do
local pWc=bb.valid(oWc.pos,IVc.data)
if pWc then
F.log(1,GBe[4355],string.format(GBe[4533],V.name(IVc.id),bb.CONTROL_WORDS[YVc],math.floor(ZVc*100+0.5)))
return pWc,oWc.cov,ZVc
end
if nWc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(qWc)
