for kbd,lbd in ipairs({0.25,0.45,0.65,0.85})do
for mbd=0,11 do
local nbd=mbd*math.pi/6+lbd
table.insert(hbd,Vector3 .new(fbd.p.X+math.cos(nbd)*fbd.r*lbd,fbd.y,fbd.p.Z+math.sin(nbd)*fbd.r*lbd))
