if Hbd then
table.insert(Ebd,{f=U.flat(Hbd),p=Hbd})
end
end
local Ibd,Jbd
local Kbd=math.max(1,math.floor(#Ebd/150))
for Lbd=1,#Ebd,Kbd do
local Mbd=Ebd[Lbd].f
local Nbd=true
for Obd,Pbd in ipairs(xbd)do
if(Pbd-Mbd).Magnitude<=wbd+2 then
Nbd=false
break
end
end
if Nbd then
local Qbd=0
for Rbd,Sbd in ipairs(Ebd)do
