end
for tcd,ucd in ipairs(Ybd.fodder)do
if#(Wbd[ucd.uuid]or{})<V.cap(ucd.u)and(bb.noSpot[ucd.uuid]or 0)<3 then
local vcd=(tonumber(ucd.data.cost)or 0)*Vbd
Ybd.more=true
table.insert(Tbd,{place=true,grif=true,cost=vcd,gain=icd*vcd,e=setmetatable({_grif=true},{__index=ucd}),what=string.format(GBe[4664],V.name(ucd.id),jcd)})
end
end
end
function bb.grifEggGain(wcd,xcd)
