return nil,nil,true
end
if Vcd==GBe[2287]then
return false
end
local Wcd=bb.grifOn()
if Wcd and(bb.grifS.done or bb.grifS.off)then
if bb.grifS.done then
return false
end
Wcd=false
end
if not bb.infinite and bb.total and bb.wave()>=bb.total-2 then
return false
end
local Xcd,Ycd=U.flat(Tcd:GetPivot().Position),tonumber(Ucd.range.Value)or 0
local Zcd,_cd,bdd,cdd=0,{},0,{}
for ddd,edd in ipairs(bb.mine or{})do
local fdd=edd~=Tcd and edd:FindFirstChild(GBe[2232])
local gdd=fdd and fdd:FindFirstChild(GBe[2548])and fdd.id.Value
if gdd and(U.flat(edd:GetPivot().Position)-Xcd).Magnitude<=Ycd then
if V.sacFodder(gdd)then
Zcd=Zcd+1
local hdd=fdd:FindFirstChild(GBe[4357])and tonumber(fdd.total_spent.Value)or 0
bdd=bdd+hdd
cdd[edd]=hdd
else
_cd[V.name(gdd)]=true
end
end
end
if next(_cd)then
bb.sacSaid=bb.sacSaid or{}
