if not ndd then
return false
end
kdd.cast={m=Tcd,at=U.now(),units=cdd,yen=bdd}
return true,string.format(GBe[4673],Zcd,Zcd==1 and GBe[1082]or GBe[2009],U.fmt(bdd),U.fmt(mdd))
end
return true,string.format(GBe[4674],Zcd,Zcd==1 and GBe[1082]or GBe[2009],U.fmt(bdd))
end
