function bb.aoePoint(qdd,rdd)
local sdd=U.flat(qdd:GetPivot().Position)
local tdd={}
for udd,vdd in ipairs(bb.samples or{})do
if(U.flat(vdd.pos)-sdd).Magnitude<=rdd*0.95 then
table.insert(tdd,vdd)
end
end
if#tdd==0 then
return nil
end
local wdd,xdd,ydd,zdd=nil,-1,-1,0
for Add,Bdd in ipairs(tdd)do
local Cdd,Ddd=0,0
for Edd,Fdd in ipairs(bb.enemies or{})do
local Gdd=Fdd.pos and(U.flat(Fdd.pos)-U.flat(Bdd.pos)).Magnitude or math.huge
if Gdd<=12 then
Ddd=Ddd+1
Cdd=Cdd+(1-Gdd/12*0.9)*(Fdd.boss and 3 or 1)
end
end
if Cdd>xdd+1e-6 or(math.abs(Cdd-xdd)<=1e-6 and Bdd.prog>ydd)then
wdd,xdd,ydd,zdd=Bdd,Cdd,Bdd.prog,Ddd
end
end
if zdd<=0 then
local Hdd=type(P.maps[bb.mapKey()])==GBe[2163]and P.maps[bb.mapKey()].dens or nil
if type(Hdd)==GBe[2163]and#Hdd>0 then
local Idd= -1
for Jdd,Kdd in ipairs(tdd)do
local Ldd=tonumber(Hdd[math.max(1,math.min(#Hdd,math.floor(Kdd.prog* #Hdd)+1))])or 0
if Ldd>Idd then
wdd,Idd=Kdd,Ldd
end
end
else
wdd=tdd[math.ceil(#tdd/2)]
end
end
return wdd and wdd.pos or nil,zdd
end
function bb.actives()
if not O.actives or bb.activeBusy then
return
end
local Mdd=tick()
