elseif Udd.ally or Udd.allyCd or Udd.allyRange then
local hed=(Udd.ally and Udd.ally.time)or(Udd.allyCd and Udd.allyCd.time)or(Udd.allyRange and Udd.allyRange.time)or 30
local ied=bb.buffedTill[Rdd.Value]
if not ied then
ied=setmetatable({},{__mode=GBe[2555]})
bb.buffedTill[Rdd.Value]=ied
end
local jed,ked,led,med={},0,0,0
for ned,oed in ipairs(bb.mine)do
