if ped:FindFirstChild(GBe[4552])and ped.target.Value~=nil then
local ued=(ied[oed]or 0)>=Ndd
if Udd.ally then
ued=bb.buffOn(ped,ted)or(ied[oed]or 0)-hed+2>=Ndd
end
if ued then
led=led+1
med=math.max(med,ied[oed]or 0)
else
ked=ked+1
