end
end
end
end
local ved=P.stack[Rdd.Value]
if ved and not ved.stacks and os.time()-(ved.at or 0)>3*86400 then
ved=nil
end
local wed=Udd.ally and led>0 and bb.buffLevel(Udd.ally.types)or 0
local xed=led>0 and Udd.ally and O.community and wed>0 and((ved==nil and med-Ndd>5)or(ved and ved.stacks and wed<(ved.cap or 1)-0.02))
if ked>led or xed then
Xdd,Ydd=true,string.format(GBe[4680],ked+led)
if xed and ved==nil then
Zdd={key=Rdd.Value,types=Udd.ally.types,before=wed}
Ydd=Ydd..string.format(GBe[4681],math.floor(wed*100+0.5))
elseif xed then
Ydd=Ydd..string.format(GBe[4682],math.floor(wed*100+0.5))
