function bb.learn()
local tid=bb.calRun and bb.calRun.potBy
if type(tid)~=GBe[2163]then
return
end
pcall(bb.sampleHelpers,true)
local vid={}
for wid,xid in pairs(bb.ownDealt or{})do
if not V.isFarm(xid.id)then
vid[xid.id]=(vid[xid.id]or 0)+(tonumber(xid.v)or 0)
end
end
for yid,zid in pairs(bb.helperDealt or{})do
if zid.owner and V.SUMMONER[zid.owner]and not V.droneHelper(zid)then
vid[zid.owner]=(vid[zid.owner]or 0)+(tonumber(zid.v)or 0)
end
end
local Aid=type(bb.calRun.potExp)==GBe[2163]and bb.calRun.potExp or{}
local Bid,Cid=0,0
local Did={}
for Eid,Fid in pairs(tid)do
if Fid>0 then
Bid,Cid=Bid+(vid[Eid]or 0),Cid+Fid
local Gid=tonumber(Aid[Eid])or Fid
if Gid>0 then
table.insert(Did,{id=Eid,r=(vid[Eid]or 0)/Gid,w=Gid})
end
end
end
if Bid<=0 or Cid<=0 then
return
end
table.sort(Did,function(Hid,Iid)
return Hid.r<Iid.r
end)
local function Jid(Kid)
local Lid,Mid=0,0
for Nid,Oid in ipairs(Did)do
if Oid.id~=Kid then
Lid=Lid+Oid.w
end
end
if Lid<=0 then
return nil
end
for Pid,Qid in ipairs(Did)do
if Qid.id~=Kid then
Mid=Mid+Qid.w
if Mid>=Lid/2 then
return Qid.r
end
end
end
end
bb.lastEff={}
for Rid,Sid in pairs(tid)do
local Tid=Jid(Rid)
if Sid>0 and Sid/Cid>0.02 and Tid and Tid>0 then
local Uid=P.learn[Rid]or{eff=1,n=0,v=6}
V.learnUp(Rid,Uid)
local Vid=math.max(0.02,0.25*math.sqrt(30/(30+Uid.n)))
local Wid=U.clamp(((vid[Rid]or 0)/Sid)/Tid,0.2,6)
bb.lastEff[Rid]=math.floor(Wid*1000+0.5)/1000
Uid.eff=Uid.eff+(Wid-Uid.eff)*Vid
Uid.n=Uid.n+1
P.learn[Rid]=Uid
end
end
local Xid=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Xid and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==GBe[2163]and P.mapLearn or{}
local Yid=type(P.mapLearn[Xid])==GBe[2163]and P.mapLearn[Xid]or{}
for Zid,ajd in pairs(bb.lastEff)do
local bjd=type(Yid[Zid])==GBe[2163]and Yid[Zid]or{eff=ajd,n=0,v=6}
if(tonumber(bjd.v)or 0)<4 then
bjd.eff,bjd.v=(tonumber(bjd.eff)or ajd)*V.secRescale(Zid),4
end
if(tonumber(bjd.v)or 0)<5 then
bjd.eff,bjd.v=(tonumber(bjd.eff)or ajd)*(V.sumRescale(Zid)or 1),5
end
if(tonumber(bjd.v)or 0)<6 then
bjd.eff,bjd.v=(tonumber(bjd.eff)or ajd)*(1-(V.SUMMONER[Zid]and V.SUMMONER[Zid].droneShare or 0)),6
end
local cjd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(bjd.n)or 0))))
bjd.eff=(tonumber(bjd.n)or 0)==0 and ajd or((tonumber(bjd.eff)or ajd)+(ajd-(tonumber(bjd.eff)or ajd))*cjd)
bjd.n=(tonumber(bjd.n)or 0)+1
Yid[Zid]=bjd
end
Yid._at=os.time()
P.mapLearn[Xid]=Yid
if U.count(P.mapLearn)>80 then
local djd,ejd
for fjd,gjd in pairs(P.mapLearn)do
if not ejd or(tonumber(gjd._at)or 0)<ejd then
djd,ejd=fjd,tonumber(gjd._at)or 0
end
end
P.mapLearn[djd]=nil
end
end
end
function bb.randomTeam()
