function bb.shieldWork(dld,eld)
local fld,gld=bb.shieldNow()
if fld<=0 or not eld or not bb.info then
return 0
end
local hld,ild=0,0
for jld,kld in ipairs(bb.team or{})do
local lld=V.rows(kld.id)
lld=lld and lld[0]
if lld and not V.isFarm(kld.id)then
hld=math.max(hld,V.dps(kld.u,0,bb.mod)*(tonumber(lld.cd)or 2)/math.max(1,V.attackInfo(lld.atk,lld.range).n))
end
end
for mld,nld in ipairs(bb.mine or{})do
local pld=nld._stats.id.Value
local qld=V.rows(pld)
local rld=qld and qld[nld._stats.upgrade and nld._stats.upgrade.Value or 0]
if rld and not V.isFarm(pld)and not V.allyBuff(pld)then
local sld=V.attackInfo(rld.atk,rld.range)
ild=ild+sld.n*sld.hits/math.max(0.3,tonumber(rld.cd)or 2)
end
end
local tld,uld=pcall(gb.wave,bb.info,math.max(1,bb.wave()),true)
local vld=V.attackInfo(eld.atk,eld.range)
return eb.shieldWork(vld.n,tonumber(eld.cd)or 2,ild,fld,tld and#uld or 1,bb.info.waveSec,hld*(bb.info.eff or 1),gld,vld.hits)
end
function bb.teamShield()
