local Gld,Hld=0,0
for Ild,Jld in ipairs(bb.mine or{})do
local Kld=Jld._stats
if not V.isFarm(Kld.id.Value)and Kld:FindFirstChild(GBe[2423])then
Gld,Hld=Gld+bb.cover(Jld:GetPivot().Position,Kld.range.Value),Hld+1
end
end
bb.reachAvg,bb.reachAt=Hld>0 and Gld/Hld or 0,U.now()
