local Xld=0
for Yld,Zld in ipairs(bb.mine or{})do
if V.isFarm(Zld._stats.id.Value)then
Xld=Xld+1
end
end
local _ld=bb.fieldCount()<16
local amd=false
for bmd,cmd in ipairs(Sld)do
local dmd=V.isFarm(cmd.id)and bb.wave()<12 and Xld<3 and not amd
if dmd then
amd=true
end
local emd=bb.roomPlan and bb.roomPlan.name==V.name(cmd.id)
local fmd=(bb.noSpot[cmd.uuid]or 0)>=3
local gmd=not fmd and(dmd or emd or V.idol(cmd.id)or bb.mergeIds[cmd.id])
local hmd=U.now()-(tonumber(bb.cardSeen[cmd.uuid])or U.now())>60
if fmd or(not gmd and bb.cardValue(cmd)<Wld*((_ld and not hmd)and 0.25 or 1))then
if bb.discardCard(cmd)then
F.log(2,GBe[4355],string.format(GBe[4774],V.name(cmd.id),fmd and GBe[4775]or(GBe[4776]..U.fmt(bb.cardValue(cmd))..GBe[4777]..U.fmt(Wld))))
bb.discards=(bb.discards or 0)+1
