function bb.baseVerdict(opd,ppd)
local qpd=(ppd.t or 0)-(opd.t or 0)
if qpd<bb.BASE_WIN-1 then
return false
end
local rpd=((tonumber(opd.base)or 0)-(tonumber(ppd.base)or 0))/qpd
if rpd<=0 or(tonumber(ppd.base)or 0)<=0 then
return false
end
local spd=ppd.base/rpd
local tpd,upd=0,0
local vpd,wpd=opd.foes or{},ppd.foes or{}
for xpd,ypd in pairs(wpd)do
if ypd.prog>=bb.BASE_END then
tpd=tpd+ypd.hp
local zpd=vpd[xpd]
if zpd then
upd=upd+math.max(0,zpd.hp-ypd.hp)
end
end
end
for Apd,Bpd in pairs(vpd)do
if Bpd.prog>=bb.BASE_END and not wpd[Apd]then
upd=upd+Bpd.hp
end
end
if tpd<=0 then
return false
end
local Cpd=upd/qpd
local Dpd=Cpd>0 and tpd/Cpd or math.huge
local Epd={baseTime=spd,loss=rpd,atEnd=tpd,rate=Cpd,killTime=Dpd}
return spd<bb.BASE_SOON and Dpd>spd*bb.BASE_MARGIN,Epd
end
