return false
end
if F.deadAt and bBe-F.deadAt<F.DEAD.every then
return false
end
local cBe,dBe,eBe=0,{},0
for fBe,gBe in ipairs(aBe.timeouts)do
if bBe-gBe.t<=300 then
cBe=cBe+1
if not dBe[gBe.name]then
dBe[gBe.name]=true
eBe=eBe+1
end
end
end
if cBe<F.DEAD.n or eBe<F.DEAD.kinds then
return false
end
F.deadAt=bBe
